-- Classic 1.60: object spawns from official Forever sniffs (beta builds 70245-70450)
-- Data source: Azeroth project, Sakhwoow/WoWForever (GPL-2). Only objects whose template we already have (English names); their guids
-- remapped to 43000000+; spawns within 3 yd of the same object already in ours left out (all their Hallow's End decorations were).

DELETE FROM `gameobject` WHERE `guid` BETWEEN 43000000 AND 43000364;

-- Herb and ore nodes: ours on Zephyris and the starting-zone variants were never pooled, so all were up at once. Each node type
-- now gets a pool of our spots plus the sniffed ones; max_limit = how many of ours were up, so the count up at once stays the same.
DELETE FROM `pool_members` WHERE `type`=1 AND `poolSpawnId` BETWEEN 1400101 AND 1400110;
DELETE FROM `pool_template` WHERE `entry` BETWEEN 1400101 AND 1400110;
